penapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/LinearFunctionData\",\"PIECEWISE_STEP\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/PiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/PiecewiseStepData\"}]},\"initial_input\":{\"type\":\"number\"},\"input_at_zero\":{\"type\":\"number\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"IncrementalCurve\",\"type\":\"object\"},\"ChargeDischarge\":{\"description\":\"A pair of values, one for the charging (`charge`) and one for the discharging (`discharge`) direction of a quantity.\",\"properties\":{\"charge\":{\"type\":\"number\"},\"discharge\":{\"type\":\"number\"}},\"required\":[\"charge\",\"discharge\"],\"title\":\"ChargeDischarge\",\"type\":\"object\"},\"InOut\":{\"description\":\"A pair of values, one for the inbound (`in`) and one for the outbound (`out`) direction of a quantity.\",\"properties\":{\"in\":{\"type\":\"number\"},\"out\":{\"type\":\"number\"}},\"title\":\"InOut\",\"type\":\"object\"},\"InputOutputCurve\":{\"description\":\"A curve whose y values are the total input `f(x)` at production level `x` — currency per hour against MW in a cost curve, fuel per hour against MW in a fuel curve. The y axis is an absolute quantity, not a rate; use `IncrementalCurve` for marginal-rate data.\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"properties\":{\"curve_type\":{\"const\":\"INPUT_OUTPUT\",\"type\":\"string\",\"default\":\"INPUT_OUTPUT\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/LinearFunctionData\",\"PIECEWISE_LINEAR\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/PiecewiseLinearData\",\"QUADRATIC\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/QuadraticFunctionData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/QuadraticFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/PiecewiseLinearData\"}]},\"input_at_zero\":{\"type\":\"number\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"InputOutputCurve\",\"type\":\"object\"},\"LinearFunctionData\":{\"description\":\"Data for a linear function `f(x) = proportional_term * x + constant_term`.\",\"properties\":{\"constant_term\":{\"type\":\"number\"},\"function_type\":{\"const\":\"LINEAR\",\"type\":\"string\",\"default\":\"LINEAR\"},\"proportional_term\":{\"type\":\"number\"}},\"required\":[\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"LinearFunctionData\",\"type\":\"object\"},\"LoadCost\":{\"description\":\"Cost representation for controllable load units\",\"properties\":{\"cost_type\":{\"const\":\"LOAD\",\"type\":\"string\",\"default\":\"LOAD\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"LoadCost\",\"type\":\"object\"},\"LossCurve\":{\"description\":\"Losses of a device as a function of the flow through it, together with the power basis the curve is expressed in. `power_units` governs BOTH axes: a loss curve's y values are power in the same base as its x values, so a change of base rescales both. This is what separates it from a cost curve, whose y axis is currency and so rides through a change of base untouched.\",\"properties\":{\"power_units\":{\"default\":\"NATURAL_UNITS\",\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/UnitSystem\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/LossValueCurve\"}},\"required\":[\"value_curve\",\"power_units\"],\"title\":\"LossCurve\",\"type\":\"object\"},\"LossValueCurve\":{\"description\":\"The shape of a loss curve, selected by `curve_type`. `INPUT_OUTPUT` gives the total loss at each flow level -- a constant loss plus a proportional loss rate, in MW of loss per MW of flow. `INCREMENTAL` gives the marginal loss rate instead, the form a piecewise model uses to give different proportional losses on different flow segments. Individual loss fields accept narrower sets of shapes than this union admits; the consuming data layer enforces that, not this schema.\",\"title\":\"LossValueCurve\",\"discriminator\":{\"mapping\":{\"INCREMENTAL\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/IncrementalCurve\",\"INPUT_OUTPUT\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/InputOutputCurve\"},\"propertyName\":\"curve_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/InputOutputCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/IncrementalCurve\"}],\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"type\":\"object\"},\"MassUnit\":{\"description\":\"Mass unit an emission quantity is reported in: kilograms, pounds, short tons (2000 lb), or metric tons (1000 kg).\",\"enum\":[\"KG\",\"LB\",\"SHORT_TON\",\"METRIC_TON\"],\"title\":\"MassUnit\",\"type\":\"string\"},\"CurveStyles\":{\"description\":\"Curve-clearing style for a bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.\",\"type\":\"integer\",\"enum\":[0,1],\"default\":0,\"title\":\"CurveStyles\"},\"CurveMultiStep\":{\"description\":\"Multi-step block indicator for a bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve style: curve style is the quantity structure, this is the time structure, and they compose.\",\"type\":\"integer\",\"enum\":[0,1],\"default\":0,\"title\":\"CurveMultiStep\"},\"MarketBidCost\":{\"description\":\"Cost representation for static (non-time-varying) market bids of energy and ancillary services.\",\"properties\":{\"cost_type\":{\"const\":\"MARKET_BID\",\"type\":\"string\",\"default\":\"MARKET_BID\"},\"minimum_energy_offer\":{\"description\":\"Minimum-energy offer: cost to operate at minimum stable level, in \$/MWh at the curve's minimum power, stored as submitted. \$/h sources convert at parse (MEO = no-load cost / P_min). Legacy scalar promotion: a bare scalar value `s` from a legacy source converts to an `InputOutputCurve` of `LinearFunctionData` with `constant_term = s` and `proportional_term = 0`.\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/InputOutputCurve\"},\"start_up\":{\"description\":\"Start-up cost at different stages of the thermal cycle (hot, warm, cold).\",\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/StartUpStages\"},\"shut_down\":{\"description\":\"Shut-down cost. Legacy scalar promotion: a bare scalar value `s` from a legacy source converts to an `InputOutputCurve` of `LinearFunctionData` with `constant_term = s` and `proportional_term = 0`.\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/InputOutputCurve\"},\"incremental_offer_curves\":{\"description\":\"Sell offer curves data as a `CostCurve` of `PiecewiseIncrementalCurve`.\",\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},\"decremental_offer_curves\":{\"description\":\"Buy offer curves data as a `CostCurve` of `PiecewiseIncrementalCurve`.\",\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},\"ancillary_service_offers\":{\"description\":\"IDs of the ancillary service components that this market bid offers into.\",\"type\":\"array\",\"items\":{\"type\":\"integer\"}},\"incremental_slope\":{\"description\":\"Linear-interpolation flag for the incremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"decremental_slope\":{\"description\":\"Linear-interpolation flag for the decremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"curve_style\":{\"description\":\"Curve-clearing style for the bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CurveStyles\"},\"curve_multistep\":{\"description\":\"Multi-step block indicator for the bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve_style: curve_style is the quantity structure, curve_multistep is the time structure, and they compose.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CurveMultiStep\"}},\"required\":[\"minimum_energy_offer\",\"start_up\",\"shut_down\",\"incremental_offer_curves\",\"decremental_offer_curves\",\"ancillary_service_offers\"],\"title\":\"MarketBidCost\",\"type\":\"object\"},\"MarketBidTimeSeriesCost\":{\"description\":\"Cost representation for time-varying market bids of energy and ancillary services. The static counterpart is MarketBidCost.\",\"properties\":{\"cost_type\":{\"const\":\"MARKET_BID_TIME_SERIES\",\"type\":\"string\",\"default\":\"MARKET_BID_TIME_SERIES\"},\"minimum_energy_offer\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/TimeSeriesInputOutputCurve\",\"description\":\"Minimum-energy offer: cost to operate at minimum stable level, in \$/MWh at the curve's minimum power, stored as submitted. \$/h sources convert at parse (MEO = no-load cost / P_min). Time-series-backed linear curve; only the TIME_SERIES_LINEAR function-data variant is admissible here — the consuming constructor rejects any other.\"},\"start_up_association_id\":{\"type\":\"integer\",\"description\":\"Store-minted id of a time series of three-stage (hot, warm, cold) start-up costs.\"},\"shut_down\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/TimeSeriesInputOutputCurve\",\"description\":\"Shut-down cost as a time-series-backed linear curve. Only the TIME_SERIES_LINEAR function-data variant is admissible here; the consuming constructor rejects any other.\"},\"incremental_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\",\"description\":\"Sell offer curves whose value curve is a time-series-backed piecewise incremental curve. Only the TIME_SERIES_INCREMENTAL variant is admissible here; any other variant is rejected by the consuming constructor.\"},\"decremental_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\",\"description\":\"Buy offer curves whose value curve is a time-series-backed piecewise incremental curve. Only the TIME_SERIES_INCREMENTAL variant is admissible here; any other variant is rejected by the consuming constructor.\"},\"ancillary_service_offers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"description\":\"IDs of the ancillary service components that this bid offers into.\"},\"incremental_slope\":{\"description\":\"Linear-interpolation flag for the incremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"decremental_slope\":{\"description\":\"Linear-interpolation flag for the decremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"curve_style\":{\"description\":\"Curve-clearing style for the bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CurveStyles\"},\"curve_multistep\":{\"description\":\"Multi-step block indicator for the bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve_style: curve_style is the quantity structure, curve_multistep is the time structure, and they compose.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CurveMultiStep\"}},\"required\":[\"cost_type\",\"minimum_energy_offer\",\"start_up_association_id\",\"shut_down\",\"incremental_offer_curves\",\"decremental_offer_curves\",\"ancillary_service_offers\"],\"title\":\"MarketBidTimeSeriesCost\",\"type\":\"object\"},\"MinMax\":{\"description\":\"A pair of values bounding a quantity from below (`min`) and from above (`max`).\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\"},\"MinMaxByKey\":{\"description\":\"A mapping from a stringified float key to the `MinMax` bound that applies at that key.\",\"additionalProperties\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/MinMax\"},\"title\":\"MinMaxByKey\",\"type\":\"object\"},\"OutageFactors\":{\"description\":\"A pair of values representing planned and forced outage factors as fractions of total availability.\",\"properties\":{\"planned\":{\"title\":\"Planned\",\"type\":\"number\"},\"forced\":{\"title\":\"Forced\",\"type\":\"number\"}},\"title\":\"OutageFactors\",\"type\":\"object\"},\"PiecewiseLinearData\":{\"description\":\"Data for a piecewise linear function defined by (x, y) points and interpolated linearly between consecutive ones. The y values are absolute values at each x, not per-segment slopes; use `PiecewiseStepData` when the data gives per-segment rates. Points run in ascending x order, and two of them define one segment.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_LINEAR\",\"type\":\"string\",\"default\":\"PIECEWISE_LINEAR\"},\"points\":{\"items\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/XY_Coords\"},\"type\":\"array\"}},\"required\":[\"points\",\"function_type\"],\"title\":\"PiecewiseLinearData\",\"type\":\"object\"},\"PiecewiseStepData\":{\"description\":\"Data for a step function, constant on each segment, defined by the x coordinates of the segment endpoints and one y value per segment. The y values are per-segment rates, not absolute values; use `PiecewiseLinearData` when the data gives a value at each point. `x_coords` ascends and holds at least two entries, and `y_coords` holds exactly one fewer.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_STEP\",\"type\":\"string\",\"default\":\"PIECEWISE_STEP\"},\"x_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"},\"y_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"}},\"required\":[\"x_coords\",\"y_coords\",\"function_type\"],\"title\":\"PiecewiseStepData\",\"type\":\"object\"},\"PollutantType\":{\"description\":\"Pollutant an emission rate is reported for, spanning greenhouse gases (`CO2`, `CO2E`, `CH4`, `N2O`), criteria pollutants (`NOX`, `SO2`, `CO`, `VOC`, `PM25`, `PM10`), and toxics (`HG`, `HAP`), with `CUSTOM` for a user-defined pollutant.\",\"enum\":[\"CO2\",\"CO2E\",\"CH4\",\"N2O\",\"NOX\",\"SO2\",\"CO\",\"VOC\",\"PM25\",\"PM10\",\"HG\",\"HAP\",\"CUSTOM\"],\"title\":\"PollutantType\",\"type\":\"string\"},\"PrimeMovers\":{\"description\":\"Prime mover of a generating unit — the engine, turbine, water wheel, or similar machine that drives the generator — using the code set from the EIA Form 923 instructions. `PVe` is photovoltaic, spelled that way so it does not collide with the `PV` bus type.\",\"enum\":[\"BA\",\"BT\",\"CA\",\"CC\",\"CE\",\"CP\",\"CS\",\"CT\",\"ES\",\"FC\",\"FW\",\"GT\",\"HA\",\"HB\",\"HK\",\"HY\",\"IC\",\"PS\",\"OT\",\"ST\",\"PVe\",\"WT\",\"WS\"],\"title\":\"PrimeMovers\",\"type\":\"string\"},\"ProductionVariableCostCurve\":{\"description\":\"Variable production cost of a device, selected by `variable_cost_type` between a curve denominated directly in currency (`COST`) and one denominated in fuel with a separate fuel price (`FUEL`).\",\"title\":\"ProductionVariableCostCurve\",\"discriminator\":{\"mapping\":{\"COST\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\",\"FUEL\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/FuelCurve\"},\"propertyName\":\"variable_cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/FuelCurve\"}],\"type\":\"object\"},\"QuadraticFunctionData\":{\"description\":\"Data for a quadratic function `f(x) = quadratic_term * x^2 + proportional_term * x + constant_term`. A non-negative `quadratic_term` makes the function convex.\",\"properties\":{\"constant_term\":{\"type\":\"number\"},\"function_type\":{\"const\":\"QUADRATIC\",\"type\":\"string\",\"default\":\"QUADRATIC\"},\"proportional_term\":{\"type\":\"number\"},\"quadratic_term\":{\"type\":\"number\"}},\"required\":[\"quadratic_term\",\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"QuadraticFunctionData\",\"type\":\"object\"},\"RenewableGenerationCost\":{\"description\":\"Cost representation for renewable generation units\",\"properties\":{\"cost_type\":{\"const\":\"RENEWABLE\",\"type\":\"string\",\"default\":\"RENEWABLE\"},\"curtailment_cost\":{\"default\":{\"variable_cost_type\":\"COST\",\"value_curve\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"vom_cost\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}}},\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},\"fixed\":{\"type\":\"number\",\"default\":0.0}},\"required\":[\"variable_operation_cost\"],\"title\":\"RenewableGenerationCost\",\"type\":\"object\"},\"ReservoirLocation\":{\"description\":\"Position of a hydro reservoir relative to its turbine: `HEAD` upstream of the turbine, typically at higher elevation; `TAIL` downstream, at lower or equal elevation.\",\"enum\":[\"HEAD\",\"TAIL\"],\"title\":\"ReservoirLocation\",\"type\":\"string\"},\"StartUpShutDown\":{\"description\":\"A pair of values, one for the start-up phase and one for the shut-down phase of a unit's cycle.\",\"properties\":{\"startup\":{\"title\":\"StartUp\",\"type\":\"number\"},\"shutdown\":{\"title\":\"ShutDown\",\"type\":\"number\"}},\"title\":\"StartUpShutDown\",\"type\":\"object\"},\"StartUpStages\":{\"description\":\"A triple of values, one for each stage of a thermal unit's start-up: `hot`, `warm`, and `cold`.\",\"properties\":{\"startup_stages_type\":{\"const\":\"STAGES\",\"type\":\"string\",\"default\":\"STAGES\"},\"cold\":{\"type\":\"number\"},\"hot\":{\"type\":\"number\"},\"warm\":{\"type\":\"number\"}},\"required\":[\"hot\",\"warm\",\"cold\"],\"title\":\"StartUpStages\",\"type\":\"object\"},\"StorageCost\":{\"description\":\"Cost representation for storage units\",\"properties\":{\"cost_type\":{\"const\":\"STORAGE\",\"type\":\"string\",\"default\":\"STORAGE\"},\"charge_variable_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},\"discharge_variable_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/CostCurve\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"shut_down\":{\"default\":0.0,\"type\":\"number\"},\"start_up\":{\"default\":0.0,\"oneOf\":[{\"type\":\"number\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ChargeDischarge\"}]},\"energy_shortage_cost\":{\"default\":0.0,\"type\":\"number\"},\"energy_surplus_cost\":{\"default\":0.0,\"type\":\"number\"}},\"required\":[\"fixed\",\"start_up\",\"shut_down\"],\"title\":\"StorageCost\",\"type\":\"object\"},\"StorageTech\":{\"description\":\"defines the storage technology used in an energy Storage system, based on the options in EIA form 923.\",\"enum\":[\"PTES\",\"LIB\",\"LAB\",\"FLWB\",\"SIB\",\"ZIB\",\"HGS\",\"LAES\",\"OTHER_CHEM\",\"OTHER_MECH\",\"OTHER_THERM\"],\"title\":\"StorageTech\",\"type\":\"string\"},\"CapitalCost\":{\"description\":\"Investment cost for candidate generation and transmission technologies which includes overnight capital costs and last-mile interconnection costs.\",\"properties\":{\"capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ValueCurve\"},\"interconnection_cost\":{\"type\":\"number\",\"default\":0.0}},\"required\":[\"capital_cost\"],\"title\":\"CapitalCost\",\"type\":\"object\"},\"StorageCapitalCost\":{\"description\":\"Investment cost for candidate generation and transmission technologies which includes overnight capital costs and last-mile interconnection costs.\",\"properties\":{\"charge_capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ValueCurve\"},\"discharge_capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ValueCurve\"},\"energy_capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ValueCurve\"},\"interconnection_cost\":{\"type\":\"number\",\"default\":0.0}},\"required\":[\"charge_capital_cost\",\"discharge_capital_cost\",\"energy_capital_cost\",\"interconnection_cost\"],\"title\":\"StorageCapitalCost\",\"type\":\"object\"},\"ThermalFuels\":{\"description\":\"Thermal fuels that reflect options in the EIA annual energy review.\",\"enum\":[\"ANTHRACITE_COAL\",\"BITUMINOUS_COAL\",\"LIGNITE_COAL\",\"SUBBITUMINOUS_COAL\",\"WASTE_COAL\",\"REFINED_COAL\",\"SYNTHESIS_GAS_COAL\",\"DISTILLATE_FUEL_OIL\",\"JET_FUEL\",\"KEROSENE\",\"PETROLEUM_COKE\",\"RESIDUAL_FUEL_OIL\",\"PROPANE\",\"SYNTHESIS_GAS_PETROLEUM_COKE\",\"WASTE_OIL\",\"BLAST_FURNACE_GAS\",\"NATURAL_GAS\",\"OTHER_GAS\",\"AG_BYPRODUCT\",\"MUNICIPAL_WASTE\",\"OTHER_BIOMASS_SOLIDS\",\"WOOD_WASTE_SOLIDS\",\"OTHER_BIOMASS_LIQUIDS\",\"SLUDGE_WASTE\",\"BLACK_LIQUOR\",\"WOOD_WASTE_LIQUIDS\",\"LANDFILL_GAS\",\"OTHER_BIOMASS_GAS\",\"NUCLEAR\",\"WASTE_HEAT\",\"TIRE_DERIVED_FUEL\",\"COAL\",\"GEOTHERMAL\",\"OTHER\"],\"title\":\"ThermalFuels\",\"type\":\"string\"},\"ThermalGenerationCost\":{\"title\":\"ThermalGenerationCost\",\"description\":\"Cost representation for thermal generation units\",\"properties\":{\"cost_type\":{\"const\":\"THERMAL\",\"type\":\"string\",\"default\":\"THERMAL\"},\"fixed\":{\"description\":\"Fixed cost of keeping the unit online. For some cost represenations this field can be duplicative\",\"type\":\"number\"},\"shut_down\":{\"description\":\"Cost to turn the unit off\",\"type\":\"number\"},\"start_up\":{\"discriminator\":{\"mapping\":{\"STAGES\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/StartUpStages\"},\"propertyName\":\"startup_stages_type\"},\"description\":\"Start-up cost can take linear or multi-stage cost\",\"oneOf\":[{\"type\":\"number\"},{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/StartUpStages\"}]},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\",\"fixed\",\"start_up\",\"shut_down\"],\"type\":\"object\"},\"TimeSeriesAverageRateCurve\":{\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_AVERAGE_RATE\",\"type\":\"string\",\"default\":\"TIME_SERIES_AVERAGE_RATE\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR or TIME_SERIES_PIECEWISE_STEP is admissible here; all other FunctionData variants, static or time-series-backed, are rejected by the consuming constructor.\"},\"initial_input_association_id\":{\"type\":[\"integer\",\"null\"],\"description\