        json="{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Candidate generation technology for a region, representing either a thermal or a renewable generation technology. It carries the capital and operating cost of new capacity together with the operating characteristics the added units take on — capacity limits, ramp and time limits, outage derating, fuel, and start-up fuel use.\",\"properties\":{\"id\":{\"description\":\"ID for individual component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component.\",\"type\":\"string\"},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`).\",\"type\":\"boolean\"},\"power_systems_type\":{\"description\":\"Corresponding type to be used in PCM modeling.\",\"type\":\"string\"},\"region\":{\"description\":\"Location where the component applies. Can be a zone or node.\",\"type\":\"array\",\"items\":{\"type\":\"integer\"}},\"prime_mover_type\":{\"description\":\"Prime mover for generator.\",\"default\":\"OT\",\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/PrimeMovers\"},\"fuel\":{\"description\":\"Fuel type according to IEA.\",\"type\":\"array\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/ThermalFuels\"}},\"cofire_start_limits\":{\"description\":\"Minimum and maximum blending level of each fuel during start-up process for multi-fuel generator. Units: 1.\",\"type\":\"object\",\"additionalProperties\":{\"\$ref\":\"https://openapi.invalid/schema/external-1e9a0d19d7563e537121.json#/\$defs/MinMax\"},\"x-unit\":\"1\",\"x-quantity\":\"Fraction\"},\"cofire_level_limits\":{\"description\":\"Minimum and maximum blending level of each fuel during normal generation process for multi-fuel generator. Units: 1.\",\"type\":\"object\",\"additionalProperties\":{\"\$ref\":\"https://openapi.invalid/schema/externa